function HologramSphere() {
  return (
    <mesh rotation={[0, 0, 0]} position={[0, 0, -5]}>
      <sphereGeometry args={[1.5, 64, 64]} />
      <meshStandardMaterial metalness={0.4} roughness={0.2} emissive="#7b00ff" emissiveIntensity={0.3} transparent opacity={0.6} color="#00ffe0" envMapIntensity={2} />
    </mesh>
  );
}
This component creates a translucent sphere with purple emissive glow and cyan base color. It uses high-poly geometry (64 segments) for smooth rendering and transparent material for the holographic look.

function WireframeIcosahedron() {
  const meshRef = useRef();
  useFrame((state) => {
    meshRef.current.rotation.x += 0.003;
    meshRef.current.rotation.y += 0.005;
    const scale = 1 + Math.sin(state.clock.elapsedTime * 0.5) * 0.05;
    meshRef.current.scale.setScalar(scale);
  });
  return (
    <mesh ref={meshRef} position={[3, 1, -8]}>
      <icosahedronGeometry args={[2, 1]} />
      <meshBasicMaterial wireframe color="#00ffe0" transparent opacity={0.3} />
    </mesh>
  );
}
Uses useFrame for continuous rotation and a sine-based scale pulse. Wireframe mode with cyan color creates the signature PromptHouse holographic wireframe look.

function GlowingTorusKnot() {
  const ref = useRef();
  useFrame(() => { ref.current.rotation.x += 0.002; ref.current.rotation.y += 0.004; });
  return (
    <mesh ref={ref} position={[-4, 2, -10]}>
      <torusKnotGeometry args={[1, 0.3, 128, 16]} />
      <meshStandardMaterial color="#1a0033" emissive="#a855f7" emissiveIntensity={0.6} metalness={0.8} roughness={0.1} />
    </mesh>
  );
}
High-quality torus knot with 128 tubular segments for smooth curves. Deep purple base with violet emissive glow creates the PromptHouse signature energy look.

function ParticleStarField({ count = 500 }) {
  const positions = useMemo(() => {
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count * 3; i++) pos[i] = (Math.random() - 0.5) * 50;
    return pos;
  }, [count]);
  const ref = useRef();
  useFrame(() => { ref.current.rotation.y += 0.0003; });
  return (
    <points ref={ref}>
      <bufferGeometry><bufferAttribute attach="attributes-position" args={[positions, 3]} /></bufferGeometry>
      <pointsMaterial size={0.08} color="#00ffe0" transparent opacity={0.6} sizeAttenuation />
    </points>
  );
}
Uses buffer geometry for optimal performance with 500+ particles. Cyan colored points with transparency create a constellation-like depth field behind UI panels.

function DNAHelix({ turns = 4, pointsPerTurn = 20 }) {
  const groupRef = useRef();
  useFrame(() => { groupRef.current.rotation.y += 0.005; });
  const total = turns * pointsPerTurn;
  const nodes = useMemo(() => Array.from({ length: total }, (_, i) => {
    const t = (i / total) * Math.PI * 2 * turns;
    const y = (i / total) * 10 - 5;
    return { a: [Math.cos(t) * 1.2, y, Math.sin(t) * 1.2], b: [Math.cos(t + Math.PI) * 1.2, y, Math.sin(t + Math.PI) * 1.2] };
  }), [turns, total]);
  return (
    <group ref={groupRef} position={[0, 0, -6]}>
      {nodes.map((n, i) => (<group key={i}>
        <mesh position={n.a}><sphereGeometry args={[0.08, 8, 8]} /><meshStandardMaterial emissive="#10b981" emissiveIntensity={1} color="#10b981" /></mesh>
        <mesh position={n.b}><sphereGeometry args={[0.08, 8, 8]} /><meshStandardMaterial emissive="#a855f7" emissiveIntensity={1} color="#a855f7" /></mesh>
      </group>))}
    </group>
  );
}
Double helix with emerald green and purple nodes. Auto-rotates on Y axis. Each strand is offset by PI radians for the characteristic double-helix shape.

function ParallaxBackground() {
  const [mouse, setMouse] = useState({ x: 0, y: 0 });
  useEffect(() => {
    const handler = (e) => setMouse({ x: (e.clientX / window.innerWidth - 0.5) * 2, y: (e.clientY / window.innerHeight - 0.5) * 2 });
    window.addEventListener('mousemove', handler);
    return () => window.removeEventListener('mousemove', handler);
  }, []);
  return (
    <div className="absolute inset-0 overflow-hidden pointer-events-none">
      <div className="absolute inset-0 opacity-20" style={{ transform: `translate(${mouse.x * 5}px, ${mouse.y * 5}px)` }}>
        {/* Far layer - dot grid */}
      </div>
      <div className="absolute inset-0 opacity-30" style={{ transform: `translate(${mouse.x * 15}px, ${mouse.y * 15}px)` }}>
        {/* Mid layer - hex pattern */}
      </div>
      <div className="absolute inset-0 opacity-40" style={{ transform: `translate(${mouse.x * 30}px, ${mouse.y * 30}px)` }}>
        {/* Near layer - floating particles */}
      </div>
    </div>
  );
}
Three depth layers at 5px, 15px, and 30px parallax intensity. Far layers are more transparent. Creates depth illusion without 3D rendering overhead.

function GlitchText({ children }) {
  return (
    <span className="relative inline-block">
      <span className="relative z-10">{children}</span>
      <span className="absolute top-0 left-0 text-cyan-400 opacity-70 animate-glitch-1" style={{ clipPath: 'inset(20% 0 60% 0)' }} aria-hidden>{children}</span>
      <span className="absolute top-0 left-0 text-pink-500 opacity-70 animate-glitch-2" style={{ clipPath: 'inset(60% 0 10% 0)' }} aria-hidden>{children}</span>
    </span>
  );
}
/* CSS:
@keyframes glitch-1 { 0%,100% { transform: translate(0); } 20% { transform: translate(-2px, 1px); } 40% { transform: translate(2px, -1px); } 60% { transform: translate(-1px, 2px); } }
@keyframes glitch-2 { 0%,100% { transform: translate(0); } 25% { transform: translate(2px, -2px); } 50% { transform: translate(-2px, 1px); } 75% { transform: translate(1px, -1px); } }
.animate-glitch-1 { animation: glitch-1 2s infinite; }
.animate-glitch-2 { animation: glitch-2 2.5s infinite; }
*/
Three layers: base text plus cyan and pink offset copies with clipPath slicing. Creates authentic holographic glitch effect with RGB channel separation.

function DataRain() {
  const canvasRef = useRef();
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    const chars = 'アイウエオカキクケコサシスセソ0123456789ABCDEF';
    const columns = Math.floor(canvas.width / 14);
    const drops = Array(columns).fill(1);
    const draw = () => {
      ctx.fillStyle = 'rgba(0,0,0,0.05)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#10b981';
      ctx.font = '12px JetBrains Mono';
      drops.forEach((y, i) => {
        const char = chars[Math.floor(Math.random() * chars.length)];
        ctx.fillStyle = y < 3 ? '#00ffe0' : `rgba(16,185,129,${0.8 - y * 0.01})`;
        ctx.fillText(char, i * 14, y * 14);
        drops[i] = y > canvas.height / 14 && Math.random() > 0.975 ? 0 : y + 1;
      });
    };
    const interval = setInterval(draw, 50);
    return () => clearInterval(interval);
  }, []);
  return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-20 pointer-events-none" />;
}
Canvas-rendered for zero DOM overhead. Uses JetBrains Mono for consistent character width. Head characters are brighter cyan, trailing characters fade to emerald green.

function CircuitTrace({ from, to }) {
  const midX = (from.x + to.x) / 2;
  const path = `M ${from.x} ${from.y} H ${midX} V ${to.y} H ${to.x}`;
  return (
    <svg className="absolute inset-0 pointer-events-none z-0" style={{ overflow: 'visible' }}>
      <path d={path} fill="none" stroke="rgba(0,255,224,0.15)" strokeWidth="1" />
      <circle r="2" fill="#00ffe0">
        <animateMotion dur="3s" repeatCount="indefinite" path={path} />
      </circle>
    </svg>
  );
}
SVG path traces with right-angle routing (horizontal then vertical then horizontal). A glowing cyan dot animates along the path using animateMotion. The trace line is faint (15% opacity) while the dot is full brightness.

